DO $review$
DECLARE v jsonb; s public.est_source_review%rowtype; q public.questions%rowtype; k public.question_keys%rowtype; a jsonb; qid uuid;
BEGIN
 FOR v IN SELECT value FROM jsonb_array_elements($payload$[{"id": "clean:HOA 073", "old_status": "duplicate", "status": "ready", "question_id": "211db957-bb1a-5ae6-88fa-e0b7cb08f842", "stem": "Which equation represents the line perpendicular to \\(2x-3y=-1\\) and passing through the midpoint of A(2, 7) and B(−1, 3)?", "choices": [{"key": "A", "text": "\\(y=\\frac23x+\\frac{14}3\\)"}, {"key": "B", "text": "\\(y=\\frac23x+\\frac{16}3\\)"}, {"key": "C", "text": "\\(y=-\\frac32x+\\frac{17}4\\)"}, {"key": "D", "text": "\\(y=-\\frac32x+\\frac{23}4\\)"}], "type": "mcq", "correct": "D", "explanation": "The given line has slope 2/3, so a perpendicular line has slope −3/2. The midpoint is (1/2, 5). Substitution into \\(y=-3x/2+b\\) gives \\(b=5+3/4=23/4\\), so D is correct.", "topic": "Algebra Foundations, Equations & Inequalities", "note": "Original compiled PDF page 49 visually checked; complete question retyped separately from unrelated fragments.", "source_document": "Math_Question_Bank_Ghoneem_Clean.pdf", "source_page": 49, "extra_sources": [], "before": {"stem": "Which of the following is the equation of the line perpendicular to the line with equation 2x − 3y = −1, and passing through the midpoint of segment AB given A(2, 7) and B(−1, 3)?", "choices": [{"key": "A", "text": "y = (2/3)x + 16/3"}, {"key": "B", "text": "y = (2/3)x + 14/3"}, {"key": "C", "text": "y = −(3/2)x + 23/4"}, {"key": "D", "text": "y = −(3/2)x + 17/4"}], "correct": "C", "explanation": "The midpoint is (1/2, 5). The given line has slope 2/3, so the required slope is −3/2. Thus y = −(3/2)x + 23/4."}}, {"id": "clean:HOA 074", "old_status": "ready", "status": "ready", "question_id": "b74a7035-6a5d-5e36-b526-1ea412b9a92e", "stem": "If \\(4^{2m+1}=32^3\\), what is \\(m+3/4\\)?", "choices": [], "type": "grid_in", "correct": "4", "explanation": "Write both sides with base 2: \\(2^{4m+2}=2^{15}\\). Thus \\(4m+2=15\\), giving \\(m=13/4\\). Therefore \\(m+3/4=16/4=4\\).", "topic": "Rational, Radical, Exponential & Logarithmic Functions", "note": "Original compiled PDF page 49 visually checked; complete question retyped separately from unrelated fragments.", "source_document": "Math_Question_Bank_Ghoneem_Clean.pdf", "source_page": 49, "extra_sources": [], "before": {"stem": "HOA 074 — Answer the original question below.", "choices": [], "correct": "4", "explanation": "4^(2m+1)=32^3 gives 2^(4m+2)=2^15, hencem=13/4; m+3/4=4."}}, {"id": "clean:HOA 075", "old_status": "worked_needs_crop", "status": "ready", "question_id": "5b4836a3-3663-58e1-a43f-86dd2ea7ece1", "stem": "If \\(\\frac1{x-1}-\\frac1{x+1}=1\\), where \\(x\\ne\\pm1\\), what is \\(11x^2\\)?", "choices": [], "type": "grid_in", "correct": "33", "explanation": "The difference is \\(2/(x^2-1)=1\\). Thus \\(x^2-1=2\\) and \\(x^2=3\\). Both possible x-values satisfy the domain restriction. Therefore \\(11x^2=33\\).", "topic": "Algebra Foundations, Equations & Inequalities", "note": "Original compiled PDF page 49 visually checked; complete question retyped separately from unrelated fragments.", "source_document": "Math_Question_Bank_Ghoneem_Clean.pdf", "source_page": 49, "extra_sources": []}, {"id": "clean:HOA 081", "old_status": "ocr_screened_not_verified", "status": "ready", "question_id": "ba77793b-339a-54eb-9aae-0af593404019", "stem": "Which ordered pair does NOT satisfy \\(|2x-1|>3y\\)?", "choices": [{"key": "A", "text": "(4, 2)"}, {"key": "B", "text": "(2, 1)"}, {"key": "C", "text": "(−1, −1)"}, {"key": "D", "text": "(−2, 1)"}], "type": "mcq", "correct": "B", "explanation": "For B, \\(|2(2)-1|=3\\) and \\(3(1)=3\\); equality does not satisfy a strict inequality. A gives 7 > 6, C gives 3 > −3, and D gives 5 > 3, so B is the only failure.", "topic": "Algebra Foundations, Equations & Inequalities", "note": "Original compiled PDF page 53 visually checked; complete question retyped separately from unrelated fragments.", "source_document": "Math_Question_Bank_Ghoneem_Clean.pdf", "source_page": 53, "extra_sources": []}, {"id": "clean:HOA 082", "old_status": "ocr_screened_not_verified", "status": "ready", "question_id": "25245654-bc79-528e-8acc-d92ed8b90da9", "stem": "What is the only integer x satisfying both \\(2x-7<5\\) and \\(3x/2-2>19/4\\)?", "choices": [{"key": "A", "text": "3"}, {"key": "B", "text": "4"}, {"key": "C", "text": "5"}, {"key": "D", "text": "6"}], "type": "mcq", "correct": "C", "explanation": "The first inequality gives x < 6. The second gives \\(3x/2>27/4\\), or x > 9/2. The only integer in (4.5, 6) is 5.", "topic": "Algebra Foundations, Equations & Inequalities", "note": "Original compiled PDF page 53 visually checked; complete question retyped separately from unrelated fragments.", "source_document": "Math_Question_Bank_Ghoneem_Clean.pdf", "source_page": 53, "extra_sources": [], "before": {"stem": "Given 2x − 7 < 5 and (3x/2) − 2 > 19/4, what is the only integer x that satisfies both inequalities?", "choices": [{"key": "A", "text": "3"}, {"key": "B", "text": "4"}, {"key": "C", "text": "5"}, {"key": "D", "text": "6"}], "correct": "C", "explanation": "The two inequalities give 4.5 < x < 6, so the only integer is 5."}}, {"id": "clean:HOA 101", "old_status": "worked_needs_crop", "status": "ready", "question_id": "501b0152-3be2-5043-a7fb-627c8358858e", "stem": "If \\(2x+y=8\\) and \\(x+3y=-1\\), what is \\(y-2x\\)?", "choices": [{"key": "A", "text": "−16"}, {"key": "B", "text": "−12"}, {"key": "C", "text": "−8"}, {"key": "D", "text": "8"}], "type": "mcq", "correct": "B", "explanation": "From the first equation y = 8 − 2x. Substitute into the second: x + 3(8 − 2x) = −1, so −5x = −25 and x = 5. Then y = −2, giving y − 2x = −2 − 10 = −12.", "topic": "Algebra Foundations, Equations & Inequalities", "note": "Original compiled PDF page 62 visually checked; complete question retyped separately from unrelated fragments.", "source_document": "Math_Question_Bank_Ghoneem_Clean.pdf", "source_page": 62, "extra_sources": []}]$payload$::jsonb) LOOP
  SELECT * INTO s FROM public.est_source_review WHERE id=v->>'id' FOR UPDATE;
  IF s.id IS NULL THEN RAISE EXCEPTION 'Missing source %',v->>'id'; END IF;
  IF EXISTS(SELECT 1 FROM public.audit_log WHERE action='source_review_20260928' AND target_id=s.id) THEN CONTINUE; END IF;
  IF s.review_status<>v->>'old_status' THEN RAISE EXCEPTION 'Source status changed %',s.id; END IF;
  qid=nullif(v->>'question_id','')::uuid;
  IF qid IS NOT NULL AND EXISTS(SELECT 1 FROM public.exams e JOIN public.attempts t ON t.exam_id=e.id
      WHERE qid=ANY(e.question_ids) AND t.status='in_progress' AND t.deadline_at>now()) THEN
   INSERT INTO public.audit_log(action,target_type,target_id,meta) VALUES('source_review_deferred_20260928','source_review',s.id,jsonb_build_object('reason','Active exam','proposed',v));
   CONTINUE;
  END IF;
  SELECT * INTO q FROM public.questions WHERE id=qid FOR UPDATE;
  SELECT * INTO k FROM public.question_keys WHERE question_id=qid FOR UPDATE;
  IF q.id IS NOT NULL AND v ? 'before' AND
    (q.stem IS DISTINCT FROM v->'before'->>'stem' OR q.choices IS DISTINCT FROM v->'before'->'choices' OR
     k.correct IS DISTINCT FROM v->'before'->'correct' OR k.explanation IS DISTINCT FROM v->'before'->>'explanation') THEN
    RAISE EXCEPTION 'Concurrent live question change %',qid;
  END IF;
  INSERT INTO public.audit_log(action,target_type,target_id,meta) VALUES('source_review_20260928','source_review',s.id,
    jsonb_build_object('before_source',to_jsonb(s),'before_question',to_jsonb(q),'before_key',to_jsonb(k),'decision',v-'assets'-'before'));
  IF v->>'status'='ready' THEN
   IF v->>'type'='mcq' AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(v->'choices') c WHERE c->>'key'=v->'correct'#>>'{}') THEN RAISE EXCEPTION 'Invalid key %',s.id; END IF;
   IF v->>'type'='grid_in' AND NOT public.answer_matches('grid_in',CASE WHEN jsonb_typeof(v->'correct')='array' THEN v->'correct'->0 ELSE v->'correct' END,v->'correct') THEN RAISE EXCEPTION 'Grader rejects %',s.id; END IF;
   a=(coalesce(q.assets,'{}'::jsonb)-'release_hold_reason')||coalesce(v->'assets','{}'::jsonb)||jsonb_build_object(
    'verified_release','2026-09-28-independent-solution-and-source-check','answer_review','2026-09-28-independent-solution-and-source-check',
    'verification_note',v->>'note','source_review_id',s.id,'verification_source',s.source_document||' page '||s.source_page);
   IF q.id IS NULL THEN
    a=a||jsonb_build_object('source','reviewed-bank-20260928','source_code',s.source_code,'source_document',s.source_document,'source_page',s.source_page);
    INSERT INTO public.questions(id,track_id,topic,difficulty,type,stem,choices,assets)
     VALUES(qid,s.track_id,v->>'topic','medium',v->>'type',v->>'stem',v->'choices',a);
    INSERT INTO public.question_keys(question_id,correct,explanation) VALUES(qid,v->'correct',v->>'explanation');
   ELSE
    UPDATE public.questions SET topic=v->>'topic',type=v->>'type',stem=v->>'stem',choices=v->'choices',assets=a WHERE id=qid;
    UPDATE public.question_keys SET correct=v->'correct',explanation=v->>'explanation' WHERE question_id=qid;
   END IF;
  END IF;
  UPDATE public.est_source_review SET review_status=v->>'status',question_id=coalesce(qid,question_id),
   worked_answer=coalesce(v->'correct',worked_answer),duplicate_of=coalesce(v->>'duplicate_of',duplicate_of),
   review_note='Rechecked 2026-09-28. '||coalesce(v->>'note','')||CASE WHEN v ? 'explanation' THEN E'\nWorked solution: '||(v->>'explanation') ELSE '' END,
   updated_at=now() WHERE id=s.id;
 END LOOP;
END;
$review$;
SELECT count(*) applied_source_decisions FROM public.audit_log WHERE action='source_review_20260928';
